-- PostgreSQL identity and library schema; additive to 001_catalog.sql.
BEGIN;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT,name TEXT,role TEXT NOT NULL DEFAULT 'MEMBER',created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS ix_sessions_user ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS favorites(user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS watch_later(user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS reactions(user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),type TEXT CHECK(type IN ('LIKE','DISLIKE')),PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS watch_progress(user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),position DOUBLE PRECISION NOT NULL DEFAULT 0,watched_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS subscriptions(user_id BIGINT NOT NULL REFERENCES users(id),channel_id BIGINT NOT NULL REFERENCES channels(id),created_at TIMESTAMPTZ,PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS playlists(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),name TEXT NOT NULL,created_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS playlist_videos(playlist_id BIGINT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,video_id BIGINT NOT NULL REFERENCES videos(id),added_at TIMESTAMPTZ,PRIMARY KEY(playlist_id,video_id));
CREATE TABLE IF NOT EXISTS comments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),body TEXT,created_at TIMESTAMPTZ,hidden BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),reason TEXT,details TEXT,status TEXT NOT NULL DEFAULT 'OPEN',created_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS user_preferences(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,pause_history BOOLEAN NOT NULL DEFAULT FALSE,autoplay_next BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS account_tokens(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('EMAIL_VERIFY','PASSWORD_RESET')),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS email_verifications(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,verified_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS user_mfa(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,secret_encrypted TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,last_totp_step BIGINT NOT NULL DEFAULT -1,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS closed_accounts(user_id BIGINT PRIMARY KEY REFERENCES users(id),closed_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS auth_security_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,kind TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS auth_rate_limits(bucket TEXT PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,window_ends BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_watch_progress_user_time ON watch_progress(user_id,watched_at DESC);
CREATE INDEX IF NOT EXISTS ix_comments_video ON comments(video_id,created_at DESC);
COMMIT;
